style.css:
@-moz-document domain("lishogi.org") {
/* Erzwingt das Ausblenden der Standard-Kanjis */
  .piece::before {
    content: none !important;
    display: none !important;
  }

  /* Formatiert die neuen Xiangqi-Grafiken auf dem Feld */
  .piece {
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
  }

  /* ==================== SENTE / WEISS (Rot) ==================== */
  .piece.king.sente { background-image: url('https://wikimedia.org') !important; }
  .piece.gold.sente { background-image: url('https://wikimedia.org') !important; }
  .piece.silver.sente { background-image: url('https://wikimedia.org') !important; }
  .piece.knight.sente { background-image: url('https://wikimedia.org') !important; }
  .piece.lance.sente { background-image: url('https://wikimedia.org') !important; }
  .piece.bishop.sente { background-image: url('https://wikimedia.org') !important; }
  .piece.rook.sente { background-image: url('https://wikimedia.org') !important; }
  .piece.pawn.sente { background-image: url('https://wikimedia.org') !important; }

  /* ==================== GOTE / SCHWARZ ==================== */
  .piece.king.gote { background-image: url('https://wikimedia.org') !important; }
  .piece.gold.gote { background-image: url('https://wikimedia.org') !important; }
  .piece.silver.gote { background-image: url('https://wikimedia.org') !important; }
  .piece.knight.gote { background-image: url('https://wikimedia.org') !important; }
  .piece.lance.gote { background-image: url('https://wikimedia.org') !important; }
  .piece.bishop.gote { background-image: url('https://wikimedia.org') !important; }
  .piece.rook.gote { background-image: url('https://wikimedia.org') !important; }
  .piece.pawn.gote { background-image: url('https://wikimedia.org') !important; }

  /* ==================== BEFÖRDERTE STEINE (Promoted) ==================== */
  .piece.promoted-rook.sente { background-image: url('https://wikimedia.org') !important; filter: drop-shadow(0 0 5px #ff0000); }
  .piece.promoted-rook.gote { background-image: url('https://wikimedia.org') !important; filter: drop-shadow(0 0 5px #ff0000); }
  .piece.promoted-bishop.sente { background-image: url('https://wikimedia.org') !important; filter: drop-shadow(0 0 5px #ff0000); }
  .piece.promoted-bishop.gote { background-image: url('https://wikimedia.org') !important; filter: drop-shadow(0 0 5px #ff0000); }
  
  .piece.promoted-pawn.sente, .piece.promoted-silver.sente, .piece.promoted-knight.sente, .piece.promoted-lance.sente { background-image: url('https://wikimedia.org') !important; filter: drop-shadow(0 0 5px #ff0000); }
  .piece.promoted-pawn.gote, .piece.promoted-silver.gote, .piece.promoted-knight.gote, .piece.promoted-lance.gote { background-image: url('https://wikimedia.org') !important; filter: drop-shadow(0 0 5px #ff0000); }
}
